/* Тренажёр CCNA · мини-лекции по дням курса (Jeremy's IT Lab, дни 1–15).
   Формат: {id,b,day,t,min,lead,secs:[{h,p|list|cli|fig}],key:[...]}
   Текст в p и list допускает <b>, <code>, <i>; термины подсвечиваются автоматически. */
window.LESSONS=[

{id:"l01",b:0,day:1,t:"Сетевые устройства",min:6,
 lead:"Сеть — это устройства, каналы между ними и правила обмена данными. Первый день курса отвечает на вопрос, кто в этой схеме за что отвечает.",
 secs:[
  {h:"Хосты, LAN и WAN",p:"Любое устройство, которое само отправляет и получает данные, — это <b>хост (host)</b>: компьютер, телефон, сервер. Хосты соединяют не напрямую, а через сетевые устройства — витой парой или оптикой. Сеть в пределах офиса, этажа или дома называют <b>локальной (LAN, Local Area Network)</b>, а канал между удалёнными площадками — <b>глобальной сетью (WAN, Wide Area Network)</b>; такой канал обычно арендуют у провайдера."},
  {h:"Коммутатор",p:"Работает на втором уровне: принимает кадр, смотрит MAC-адрес получателя и отправляет кадр в один нужный порт. Если адрес ему пока неизвестен, кадр уходит во все порты, кроме входного. Каждый порт коммутатора — отдельный <b>коллизионный домен (collision domain)</b>, а вот <b>широковещательный домен (broadcast domain)</b> у всех портов общий.",
   fig:{w:540,h:170,n:[[55,45,"pc","PC1"],[55,120,"pc","PC2"],[215,82,"sw","SW1"],[380,82,"rtr","R1"],[500,82,"cloud","Интернет"]],e:[[0,2],[1,2],[2,3],[3,4]]}},
  {h:"Маршрутизатор",p:"Работает на третьем уровне и соединяет разные сети между собой: смотрит IP-адрес получателя, ищет подходящую запись в таблице маршрутизации и отправляет пакет дальше. Каждый его интерфейс — граница широковещательного домена: broadcast через маршрутизатор не проходит. Поэтому крупную сеть делят маршрутизаторами не только ради связности, но и чтобы лишний трафик не расходился по всей организации."},
  {h:"Хаб и повторитель",p:"<b>Хаб (hub)</b> — устройство первого уровня: он повторяет сигнал во все порты, поэтому все подключённые устройства делят одну среду, работают в полудуплексе и мешают друг другу. В живых сетях его вытеснил коммутатор, но на экзамене хаб встречается как пример «один коллизионный домен на всех»."}
 ],
 key:["Коммутатор разделяет коллизионные домены, маршрутизатор — широковещательные.","Хаб просто повторяет сигнал во все порты и создаёт коллизии.","LAN — своя территория, WAN — арендованный канал между площадками."]},

{id:"l02",b:0,day:2,t:"Интерфейсы и кабели",min:7,
 lead:"Физика канала: какой кабель куда подходит, чем прямой отличается от перекрёстного и почему дуплекс важнее скорости.",
 secs:[
  {h:"Витая пара",p:"В кабеле <b>UTP (unshielded twisted pair)</b> восемь проводников, свитых в четыре пары. Скрутка нужна против помех: наводка действует на оба провода пары одинаково, и приёмник, который смотрит на <i>разницу</i> напряжений, помеху вычитает. Разъём — <b>RJ-45</b>, распиновка по стандартам <b>T568A</b> и <b>T568B</b> (в T568B первая пара — бело-оранжевый и оранжевый)."},
  {h:"Прямой и перекрёстный",p:"<b>Прямой кабель (straight-through)</b> соединяет разные по логике устройства: ПК — коммутатор, коммутатор — маршрутизатор. <b>Перекрёстный (crossover)</b> — одинаковые: ПК — ПК, коммутатор — коммутатор. Современные порты умеют <b>Auto-MDIX</b> и сами меняют передающую и принимающую пары местами, поэтому канал поднимется с любым кабелем — но на экзамене правило спрашивают в чистом виде."},
  {h:"Скорости и стандарты",list:["<b>10BASE-T</b> — 10 Мбит/с, две пары, до 100 м.","<b>100BASE-T</b> — 100 Мбит/с, две пары, до 100 м.","<b>1000BASE-T</b> — 1 Гбит/с, все четыре пары в обе стороны одновременно, до 100 м.","<b>1000BASE-LX</b> — одномодовое оптоволокно (single-mode), километры; <b>SX</b> — многомодовое (multimode), сотни метров."]},
  {h:"Дуплекс",p:"<b>Полный дуплекс (full duplex)</b> — передача и приём одновременно, это норма для канала коммутатор — устройство. <b>Полудуплекс (half duplex)</b> остался от хабов: передавать можно только по очереди. Если на концах канала настроены разные режимы, канал поднимется, но будет терять кадры и копить поздние коллизии — классическая ошибка <b>несовпадение дуплекса (duplex mismatch)</b>."}
 ],
 key:["Скрутка пар защищает от помех, а не просто удобна при монтаже.","ПК — коммутатор: прямой кабель. Одинаковые устройства: перекрёстный.","Предел витой пары — 100 метров; дальше нужна оптика.","Дуплекс должен совпадать на обоих концах."]},

{id:"l03",b:0,day:3,t:"Модель OSI и стек TCP/IP",min:7,
 lead:"Модель нужна, чтобы описывать сеть по частям: каждый уровень решает свою задачу и пользуется услугами соседнего снизу.",
 secs:[
  {h:"Семь уровней",list:["<b>7 Прикладной (application)</b> — HTTP, DNS, FTP: что именно передаём.","<b>6 Представления (presentation)</b> — формат и шифрование данных.","<b>5 Сеансовый (session)</b> — начало, поддержание и завершение диалога.","<b>4 Транспортный (transport)</b> — TCP и UDP: порты, надёжность, управление потоком.","<b>3 Сетевой (network)</b> — IP: логическая адресация и выбор пути.","<b>2 Канальный (data link)</b> — Ethernet: MAC-адреса, кадры, проверка ошибок.","<b>1 Физический (physical)</b> — сигналы, кабели, разъёмы, биты."]},
  {h:"Инкапсуляция",p:"Данные приложения по пути вниз обрастают заголовками: транспортный уровень добавляет свой и получается <b>сегмент (segment)</b>, сетевой — <b>пакет (packet)</b>, канальный добавляет заголовок и концевик — получается <b>кадр (frame)</b>, физический превращает всё это в сигналы. На приёме происходит обратное — <b>деинкапсуляция</b>. Общее имя для «заголовок плюс данные» на любом уровне — <b>PDU</b>: пакет IP — это L3 PDU, кадр Ethernet — L2 PDU."},
  {h:"Как это соотносится с TCP/IP",p:"В стеке TCP/IP уровней четыре: сетевой доступ (link), сетевой (internet), транспортный и прикладной. Прикладной уровень TCP/IP покрывает уровни 5–7 модели OSI, а сетевой доступ — уровни 1–2. Номерами при этом пользуются по OSI: TCP называют протоколом четвёртого уровня, IP — третьего."},
  {h:"Зачем это на практике",p:"Уровни задают язык диагностики. «Канал не поднимается» — это уровень 1: кабель, разъём, скорость. «Кадры ходят, пинг не идёт» — уровень 3: адрес, маска, шлюз, маршрут. «Пинг идёт, приложение не работает» — уровень 4 и выше: порт, служба, брандмауэр. Проверять снизу вверх быстрее, чем гадать."}
 ],
 key:["Сегмент → пакет → кадр: на каждом уровне свой заголовок.","IP — уровень 3, TCP и UDP — уровень 4, Ethernet — уровни 1–2.","Диагностику ведут снизу вверх: сначала физика, потом адресация, потом приложение."]},

{id:"l04",b:0,day:4,t:"Командная строка IOS",min:8,
 lead:"IOS — операционная система устройств Cisco. Настройка идёт текстом: важно понимать, в каком режиме вы находитесь и где сохраняется результат.",
 secs:[
  {h:"Как подключиться",p:"Первый раз — консольным кабелем к порту <code>console</code>: пароля ещё нет, адреса тоже. Дальше удобнее по сети: <b>SSH</b> (шифрует, порт 22) или устаревший <b>Telnet</b> (открытым текстом, порт 23). Для удалённого доступа нужен адрес на интерфейсе или на VLAN управления, пароль и, для SSH, сгенерированные ключи."},
  {h:"Режимы",cli:"Switch>                        ← пользовательский (user EXEC)\nSwitch> enable\nSwitch#                        ← привилегированный (privileged EXEC)\nSwitch# configure terminal\nSwitch(config)#                ← глобальная настройка\nSwitch(config)# interface gi0/1\nSwitch(config-if)#             ← настройка интерфейса"},
  {h:"Что где смотреть",p:"<code>show running-config</code> — конфигурация, которая работает <i>сейчас</i> (в оперативной памяти RAM). <code>show startup-config</code> — та, что загрузится после перезагрузки (в NVRAM). Пока вы не выполнили <code>copy running-config startup-config</code> (сокращённо <code>wr</code>), все правки живут только до отключения питания. Отменяют команду тем же текстом с приставкой <code>no</code>."},
  {h:"Экономия нажатий",list:["<code>?</code> — список доступных команд или вариантов продолжения.","Tab — дописать команду до конца.","Сокращения работают, пока они однозначны: <code>int gi0/1</code>, <code>sh ip int br</code>.","<code>end</code> — сразу в привилегированный режим, <code>exit</code> — на один уровень вверх.","<code>do</code> перед командой show позволяет выполнить её, не выходя из режима настройки."]}
 ],
 key:["Правки попадают в running-config и теряются при перезагрузке без copy run start.","enable → configure terminal → interface: режимы идут строго по порядку.","Отмена команды — та же команда с no."]},

{id:"l05",b:0,day:5,t:"Коммутация Ethernet: кадр и адреса",min:7,
 lead:"Ethernet описывает, как выглядит кадр и как устройства в локальной сети адресуют друг друга.",
 secs:[
  {h:"Поля кадра",p:"Кадр начинается с <b>преамбулы</b> — по ней приёмник понимает, что пошли данные. Дальше <b>MAC-адрес получателя</b>, <b>MAC-адрес отправителя</b>, поле <b>типа (EtherType)</b> — что лежит внутри (<code>0x0800</code> — IPv4, <code>0x86DD</code> — IPv6, <code>0x0806</code> — ARP), сами данные и в конце — <b>контрольная сумма кадра (FCS)</b>."},
  {h:"FCS только обнаруживает ошибки",p:"Получатель считает контрольную сумму заново и сравнивает с полем FCS. Не совпало — кадр <b>молча отбрасывается</b>. Ethernet не просит повторить передачу и не исправляет биты: потерю заметит TCP по подтверждениям и перешлёт данные сам. Это и есть <b>обнаружение ошибок (error detection)</b> без <b>восстановления (error recovery)</b>."},
  {h:"MAC-адрес",p:"48 бит, записывается шестнадцатеричными парами: <code>00:1A:2B:3C:4D:5E</code>. Первые 24 бита — <b>OUI</b>, идентификатор производителя, назначенный IEEE; остальные производитель присваивает сам. Адрес зашит в сетевой плате, поэтому его называют физическим."},
  {h:"Три типа адресов",list:["<b>Одноадресный (unicast)</b> — ровно один интерфейс.","<b>Широковещательный (broadcast)</b> — <code>FFFF.FFFF.FFFF</code>, все устройства сегмента.","<b>Групповой (multicast)</b> — заинтересованная группа устройств."]},
  {h:"Минимальный размер",p:"Кадр не может быть короче 64 байт. Если данных меньше, отправитель добавляет заполнение (padding). Кадры короче 64 байт считаются повреждёнными и попадают в счётчик <b>runts</b>."}
 ],
 key:["EtherType говорит, пакет какого протокола лежит в кадре.","Несовпал FCS — кадр отбрасывается без повторной передачи.","Первые 24 бита MAC-адреса — OUI производителя.","Минимальный кадр — 64 байта, короче — runts."]},

{id:"l06",b:0,day:6,t:"Коммутация Ethernet: таблица MAC",min:7,
 lead:"Коммутатор не настраивают вручную под каждый адрес: он учится сам, глядя на адреса отправителей.",
 secs:[
  {h:"Обучение",p:"Приняв кадр, коммутатор запоминает пару «<b>MAC-адрес отправителя</b> — порт, откуда кадр пришёл» в <b>таблице MAC-адресов</b>. Записи живут ограниченное время (по умолчанию 5 минут) и обновляются при каждом новом кадре с этого адреса. Смотрят таблицу командой <code>show mac address-table</code>."},
  {h:"Три решения по кадру",list:["<b>Пересылка (forward)</b> — адрес получателя в таблице: кадр уходит в один указанный порт.","<b>Затопление (flooding)</b> — адреса в таблице нет, либо это broadcast или неизвестный multicast: кадр уходит во все порты, кроме входного.","<b>Фильтрация (filtering)</b> — получатель находится в том же порту, откуда кадр пришёл: пересылать некуда, кадр отбрасывается."]},
  {h:"Почему flooding — это нормально",p:"Первый кадр к неизвестному адресу всегда рассылается по всем портам, и ответ от получателя тут же добавляет нужную запись в таблицу. Так коммутатор наполняет таблицу без всякой настройки. Проблемой затопление становится только при петле в топологии — от этого и защищает протокол STP."},
  {h:"Сколько живёт запись",p:"У каждой записи есть <b>таймер бездействия (inactivity timer)</b>: он обнуляется при каждом новом кадре от этого адреса и растёт, пока устройство молчит. Запись, которая молчала дольше времени хранения (по умолчанию 300 секунд), удаляется. Если место в таблице кончилось, коммутатор вытесняет самые «молчаливые» записи — с наибольшим таймером."},
  {h:"Три метода обработки кадра",list:["<b>С буферизацией (store-and-forward)</b> — кадр принимается целиком, проверяется FCS, и только потом пересылается. Так работают современные коммутаторы.","<b>Без буферизации (cut-through)</b> — передача начинается, едва прочитан MAC-адрес получателя: задержка минимальна, но битые кадры уходят дальше, ведь FCS лежит в конце кадра.","<b>Без фрагментации (fragment-free)</b> — компромисс: коммутатор ждёт первые 64 байта, на которые приходится большинство коллизий, и потом начинает передачу."]},
  {h:"CSMA/CD и коллизии",p:"В полудуплексном сегменте (хаб или неверно настроенный порт) устройства слушают среду перед передачей — это <b>CSMA/CD</b>. Если два устройства начали одновременно, происходит <b>коллизия</b>: обе передачи прекращаются, посылается jam-сигнал, и каждое устройство ждёт случайное время перед повтором. В полном дуплексе коллизий не бывает вообще, поэтому CSMA/CD там отключён."},
  {h:"Что ещё делает коммутатор",p:"Кроме пересылки и обучения у коммутатора есть третья базовая задача — <b>STP</b>: блокировать лишние порты, чтобы в топологии с резервными каналами кадры не ходили по кругу. Без STP один широковещательный кадр в кольце из коммутаторов размножится и положит сеть. Подробно это тема дней 20–22. Ещё одно преимущество перед хабом: коммутатор <b>согласует скорости</b> — приняв кадр в буфер, он отправляет его в другой порт на скорости этого порта, поэтому устройства на 100 Мбит/с и 1 Гбит/с спокойно работают через один коммутатор."}
 ],
 key:["Таблица MAC наполняется по адресам отправителей, а решения принимаются по адресу получателя.","Неизвестный одноадресный кадр и broadcast рассылаются во все порты, кроме входного.","Store-and-forward проверяет FCS до пересылки, cut-through — нет.","Коллизии существуют только в полудуплексе."]},

{id:"l07",b:0,day:7,t:"IPv4-адресация: адрес, маска, группы",min:8,
 lead:"IP-адрес нужен, чтобы пакет нашёл получателя в любой сети мира. Адреса не выдают вразнобой: они сгруппированы, и именно это делает маршрутизацию возможной.",
 secs:[
  {h:"Как записывается адрес",p:"IPv4-адрес — это 32 бита. Для людей его пишут <b>десятичной записью с точками (DDN)</b>: каждый байт переводят в десятичное число, получается четыре <b>октета</b> со значениями 0–255. Адрес <code>168.1.1.1</code> в двоичном виде — <code>10101000 00000001 00000001 00000001</code>. Адрес принадлежит не компьютеру, а <b>интерфейсу</b>: у ноутбука с проводом и Wi-Fi адресов два, у маршрутизатора — по одному на каждый работающий интерфейс."},
  {h:"Сетевая и хостовая части",p:"Адрес делится на две части: <b>сетевая (network)</b> одинакова у всех адресов группы, <b>хостовая (host)</b> различает устройства внутри неё. Где именно проходит граница, говорит <b>маска (subnet mask)</b>: единицы маски — сетевая часть, нули — хостовая. <code>255.255.255.0</code> и <code>/24</code> — одна и та же маска, записанная по-разному."},
  {h:"Два правила группировки",p:"Правила простые, но ошибиться в проекте на них легко: адреса <b>одной</b> подсети не должны быть разделены маршрутизатором, а адреса, разделённые маршрутизатором, обязаны быть из <b>разных</b> подсетей. Одна подсеть — один канал: LAN или WAN. Иначе маршрутизация ломается, ведь для остальной сети вся подсеть выглядит как находящаяся с одной стороны маршрутизатора."},
  {h:"Классы адресов",list:["<b>A</b> — первый октет 1–126, классовая маска /8, огромные сети (всего их 126).","<b>B</b> — 128–191, маска /16, по 65 534 адреса хоста.","<b>C</b> — 192–223, маска /24, по 254 адреса хоста.","<b>D</b> — 224–239, групповая рассылка (multicast).","<b>E</b> — 240–255, экспериментальный. Отдельно стоит 127 — это loopback, проверка своего же стека."]},
  {h:"Частные адреса",p:"Документ <b>RFC 1918</b> выделил блоки, которые не маршрутизируются в Интернете и потому свободно используются внутри организаций: <code>10.0.0.0/8</code>, <code>172.16.0.0/12</code> (то есть 172.16–172.31) и <code>192.168.0.0/16</code>. Наружу они выходят через <b>NAT</b>. Не путайте с <code>169.254.0.0/16</code> — это APIPA, адрес, который хост берёт сам, когда не получил ответа от DHCP."}
 ],
 key:["Маска отделяет сетевую часть адреса от хостовой; /24 и 255.255.255.0 — одно и то же.","Одна подсеть = один канал, маршрутизатор её не разрывает.","Класс определяется первым октетом; 224–239 — multicast, 127 — loopback.","Частные блоки: 10/8, 172.16/12, 192.168/16."]},

{id:"l08",b:0,day:8,t:"IPv4-адресация: адрес сети, broadcast, шлюз",min:8,
 lead:"В каждой подсети два адреса заняты служебно, а один хост обязательно нужно знать по имени — шлюз по умолчанию.",
 secs:[
  {h:"Три вида адресов в подсети",p:"<b>Адрес сети (network address)</b> — самый первый, все биты хостовой части нули: он обозначает саму подсеть и хосту не назначается. <b>Широковещательный адрес (broadcast)</b> — самый последний, все биты хостовой части единицы: пакет на него получат все хосты подсети. Всё, что между ними, — рабочие адреса хостов."},
  {h:"Сколько адресов доступно",p:"Если на хостовую часть осталось <i>h</i> бит, то адресов в подсети 2<sup>h</sup>, а назначить хостам можно <b>2<sup>h</sup> − 2</b>: минус адрес сети и минус broadcast. Для /24 это 254, для /26 — 62, для /28 — 14, для /30 — ровно 2 (столько и нужно каналу между двумя маршрутизаторами)."},
  {h:"Шлюз по умолчанию",p:"Хост сравнивает адрес получателя со своим и своей маской. Получатель в той же подсети — кадр уходит ему напрямую. В другой — пакет отправляется на <b>шлюз по умолчанию (default gateway)</b>, то есть на маршрутизатор с интерфейсом в этой же подсети. Важная деталь: IP-адрес получателя в пакете при этом <b>не меняется</b> на адрес шлюза — шлюзу адресован только кадр, по MAC-адресу."},
  {h:"Особые адреса",list:["<code>127.0.0.1</code> — loopback, проверка собственного стека TCP/IP.","<code>169.254.x.x</code> — APIPA: DHCP не ответил, хост назначил адрес сам.","<code>255.255.255.255</code> — широковещательный адрес всей локальной сети.","<code>0.0.0.0</code> — «любой адрес»: так записывают маршрут по умолчанию и так хост обозначает себя, пока не получил адрес."]}
 ],
 key:["В подсети хостам доступно 2^h − 2 адреса: первый и последний заняты.","В другую подсеть пакет идёт через шлюз по умолчанию, но IP получателя остаётся конечным.","/30 — стандартная маска для канала точка-точка."]},

{id:"l09",b:0,day:9,t:"Интерфейсы коммутатора и их ошибки",min:7,
 lead:"Большая часть проблем в локальной сети видна в двух командах. Разберём, что они показывают и о чём говорят счётчики ошибок.",
 secs:[
  {h:"Состояние портов",cli:"SW1# show interfaces status\nPort    Name   Status       Vlan   Duplex  Speed Type\nGi0/1          connected    1      a-full  a-1000 10/100/1000BaseTX\nGi0/2          notconnect   1        auto   auto 10/100/1000BaseTX\nGi0/3          err-disabled 1        auto   auto 10/100/1000BaseTX"},
  {h:"Что означают статусы",list:["<b>connected</b> — канал работает, кадры ходят.","<b>notconnect</b> — сигнала нет: кабель не подключён, обрыв или выключен дальний конец.","<b>administratively down</b> — порт выключен вручную командой <code>shutdown</code>.","<b>err-disabled</b> — коммутатор сам выключил порт из-за нарушения политики (например, port security или BPDU Guard). Поднимают парой <code>shutdown</code> / <code>no shutdown</code>.","Приставка <b>a-</b> в полях дуплекса и скорости означает, что значение согласовано автоматически (autonegotiation)."]},
  {h:"Счётчики ошибок",p:"В выводе <code>show interfaces gi0/1</code> смотрят на несколько строк. <b>CRC / input errors</b> — кадры с неверной контрольной суммой: почти всегда физика, то есть кабель, разъём, помехи или превышенная длина. <b>Runts</b> — кадры короче 64 байт, <b>giants</b> — длиннее допустимого. <b>Late collisions</b> — коллизии, случившиеся слишком поздно: верный признак <b>несовпадения дуплекса</b>. Коллизии в полудуплексе сами по себе нормальны, в полном дуплексе их быть не должно."},
  {h:"Базовая настройка порта",cli:"SW1(config)# interface gi0/1\nSW1(config-if)# description Uplink-to-R1\nSW1(config-if)# speed 1000\nSW1(config-if)# duplex full\nSW1(config-if)# no shutdown"}
 ],
 key:["err-disabled ставит сам коммутатор, administratively down — человек.","Ошибки CRC — ищите физику: кабель, разъём, длину.","Поздние коллизии = duplex mismatch.","Скорость и дуплекс задают либо авто на обоих концах, либо жёстко на обоих."]},

{id:"l10",b:0,day:10,t:"Заголовок IPv4",min:6,
 lead:"Двадцать байт, которые маршрутизатор читает у каждого пакета. Знать наизусть порядок полей не нужно, а понимать назначение основных — обязательно.",
 secs:[
  {h:"Основные поля",list:["<b>Version</b> — версия протокола: 4.","<b>Header Length</b> — длина заголовка: обычно 20 байт, больше — если есть опции.","<b>DSCP</b> — метка приоритета для QoS.","<b>Total Length</b> — длина всего пакета вместе с данными.","<b>Identification, Flags, Fragment Offset</b> — фрагментация: по этим полям получатель собирает пакет, который в пути разрезали на части.","<b>TTL</b> — счётчик оставшихся переходов.","<b>Protocol</b> — что внутри: 1 — ICMP, 6 — TCP, 17 — UDP, 89 — OSPF.","<b>Header Checksum</b> — контрольная сумма заголовка.","<b>Source / Destination IP Address</b> — по 32 бита."]},
  {h:"TTL и traceroute",p:"Каждый маршрутизатор уменьшает <b>TTL</b> на единицу. Дошло до нуля — пакет отбрасывается, а отправителю уходит сообщение ICMP <i>Time Exceeded</i>. Так зацикленный пакет не живёт вечно — и на этом же построен <b>traceroute</b>: утилита посылает пакеты с TTL 1, 2, 3… и по ответам собирает список маршрутизаторов на пути."},
  {h:"Контрольная сумма только заголовка",p:"IPv4 проверяет контрольной суммой <b>только свой заголовок</b>, а не данные: за целостность данных отвечают уровни ниже (FCS кадра) и выше (контрольная сумма TCP или UDP). Поскольку TTL меняется на каждом переходе, контрольную сумму заголовка маршрутизатор обязан пересчитывать. В IPv6 от этого поля отказались вовсе — ради скорости обработки."}
 ],
 key:["Protocol = 6 для TCP, 17 для UDP, 1 для ICMP.","TTL уменьшается каждым маршрутизатором; на нуле — ICMP Time Exceeded.","Контрольная сумма в IPv4 покрывает только заголовок."]},

{id:"l11",b:1,day:11,t:"Статическая маршрутизация",min:8,
 lead:"Маршрутизатор пересылает пакет только туда, о чём знает. Разберём, откуда в таблице берутся записи и как добавить свою.",
 secs:[
  {h:"Откуда берутся маршруты",p:"Подняв интерфейс с адресом и маской, маршрутизатор сам добавляет в таблицу запись <code>C</code> (<b>connected</b>) — про подсеть этого интерфейса — и запись <code>L</code> (<b>local</b>) с маской /32 на собственный адрес. Про <i>чужие</i> подсети он не знает ничего: их задают вручную статическими маршрутами или изучают протоколом маршрутизации.",
   fig:{w:560,h:160,n:[[55,65,"pc","PC1","10.0.1.10"],[200,65,"rtr","R1","10.0.1.1"],[380,65,"rtr","R2","10.0.2.1"],[520,65,"srv","SRV","10.0.2.20"]],e:[[0,1],[1,2,"10.0.12.0/30",".1",".2"],[2,3]]}},
  {h:"Как задать маршрут",cli:"R1(config)# ip route 10.0.2.0 255.255.255.0 10.0.12.2\n↑ сеть           ↑ маска          ↑ следующий переход (next hop)\n\nR1(config)# ip route 0.0.0.0 0.0.0.0 10.0.12.2\n↑ маршрут по умолчанию: всё, для чего нет точной записи"},
  {h:"Следующий переход или интерфейс",p:"Обычно указывают <b>IP-адрес следующего маршрутизатора</b>, и он обязан находиться в подключённой подсети — иначе маршрут не попадёт в таблицу. На каналах точка-точка можно указать исходящий интерфейс. У напрямую подключённых подсетей следующего перехода нет вообще: последний маршрутизатор сам собирает кадр с MAC-адресом хоста-получателя."},
  {h:"Правило самого точного совпадения",p:"Если адресу подходят несколько записей, побеждает запись с <b>самой длинной маской</b> — она точнее. Для пакета к <code>10.1.1.55</code> при наличии <code>10.0.0.0/8</code>, <code>10.1.0.0/16</code> и <code>10.1.1.0/24</code> будет выбрана третья. Маршрут по умолчанию <code>0.0.0.0/0</code> — самый неточный, поэтому он используется последним."},
  {h:"Плавающий маршрут",p:"Два статических маршрута к одной сети с разной <b>административной дистанцией</b> дают простое резервирование: обычный маршрут (дистанция 1) работает, а второй — <b>плавающий (floating static)</b> с дистанцией, скажем, 5 — лежит в запасе и попадает в таблицу, только когда первый пропадёт."}
 ],
 key:["C и L появляются сами, чужие сети нужно задавать или изучать.","ip route сеть маска следующий-переход; 0.0.0.0/0 — маршрут по умолчанию.","Выбирается запись с самой длинной маской.","Плавающий маршрут = резерв за счёт большей административной дистанции."]},

{id:"l12",b:1,day:12,t:"Жизнь пакета",min:9,
 lead:"Соберём всё вместе: что происходит с данными от нажатия Enter до ответа сервера. Это любимая тема экзамена и лучший способ проверить, понятны ли уровни.",
 secs:[
  {h:"Шаг нулевой: имя в адрес",p:"Приложение знает имя, а не адрес, поэтому первым уходит запрос к серверу <b>DNS</b>: «какой адрес у этого имени?». Ответ содержит IP-адрес, и только после этого хост может собрать пакет. Запрос DNS маршрутизаторы обрабатывают как любой другой пакет — по адресу получателя."},
  {h:"Шаг первый: свой или чужой",p:"Хост сравнивает адрес получателя со своей подсетью. Тот же адрес сети — значит, получатель рядом, кадр адресуется прямо ему. Другая подсеть — кадр адресуется <b>шлюзу по умолчанию</b>. При этом IP-адрес получателя в пакете остаётся конечным: меняется только адресат кадра."},
  {h:"Шаг второй: узнать MAC по ARP",p:"Чтобы собрать кадр, нужен MAC-адрес соседа, а известен только его IP. Тогда хост рассылает широковещательный <b>запрос ARP</b>: «у кого адрес 10.0.1.1 — сообщите свой MAC». Владелец адреса отвечает одноадресным <b>ответом ARP</b>. Пара «IP — MAC» сохраняется в <b>кеше ARP</b> на несколько минут, поэтому ARP работает не перед каждым пакетом, а изредка. На компьютере кеш смотрят командой <code>arp -a</code>."},
  {h:"Шаг третий: маршрутизатор за маршрутизатором",p:"Приняв кадр, маршрутизатор действует по одному и тому же порядку: <b>1)</b> проверяет контрольную сумму кадра (FCS) и при ошибке отбрасывает его; <b>2)</b> снимает заголовок и концевик канального уровня; <b>3)</b> ищет в таблице маршрутизации самое точное совпадение для адреса получателя; <b>4)</b> заново инкапсулирует пакет в кадр, подходящий для исходящего интерфейса, и отправляет. И так на каждом переходе."},
  {h:"Что меняется, а что нет",list:["<b>IP-адреса</b> — сквозные: те же от отправителя до получателя (меняет их только NAT).","<b>MAC-адреса</b> — местные: переписываются на каждом канале.","<b>TTL</b> — уменьшается на единицу каждым маршрутизатором.","<b>Заголовок канального уровня</b> — снимается и создаётся заново, на разных участках он может быть даже разного типа: Ethernet, HDLC, PPP."]},
  {h:"Проверка: ping",p:"Утилита <b>ping</b> отправляет <b>эхо-запрос ICMP</b> и ждёт <b>эхо-ответ</b>. Успешный ping означает, что уровни 1–3 работают в обе стороны: адреса, маски, маршруты и обратные маршруты на месте. Приложения он не проверяет — для этого нужны порты и <code>telnet</code> на порт или другие средства."}
 ],
 key:["DNS → сравнение подсети → ARP → кадр: порядок всегда такой.","IP сквозные, MAC локальные для участка, TTL уменьшается.","Маршрутизатор: FCS → снять L2 → найти маршрут → инкапсулировать заново.","Ping проверяет уровни 1–3, но ничего не говорит о приложении."]},

{id:"l13",b:1,day:13,t:"Подсети: считаем границы",min:9,
 lead:"Подсети — главный навык экзамена. Считать нужно быстро и без калькулятора, поэтому важнее метод, чем формулы.",
 secs:[
  {h:"Зачем делить",p:"Классовая сеть слишком велика: у класса B — 65 534 адреса, а каналу между маршрутизаторами нужно два. <b>Деление на подсети (subnetting)</b> забирает несколько бит у хостовой части и отдаёт их сетевой. Результат: вместо одной огромной группы — много групп подходящего размера, меньше потерянных адресов и меньше широковещательных доменов."},
  {h:"Размер блока",p:"Главный приём: <b>размер блока (block size) = 256 − значение интересного октета маски</b>. Для /26 маска <code>255.255.255.192</code>, блок 256 − 192 = 64, значит границы подсетей идут через 64: .0, .64, .128, .192. Для /27 блок 32, для /28 — 16, для /30 — 4. Адреса сети — это и есть начала блоков.",
   cli:"/25 → 255.255.255.128 → блок 128\n/26 → 255.255.255.192 → блок  64\n/27 → 255.255.255.224 → блок  32\n/28 → 255.255.255.240 → блок  16\n/29 → 255.255.255.248 → блок   8\n/30 → 255.255.255.252 → блок   4"},
  {h:"Порядок решения",list:["Записать маску и найти интересный октет — тот, где есть и единицы, и нули.","Посчитать размер блока.","Найти начало блока, в который попадает адрес: это <b>адрес сети</b>.","Начало следующего блока минус 1 — это <b>широковещательный адрес</b>.","Всё между ними — диапазон хостов."]},
  {h:"Пример",p:"Дан адрес <code>192.168.10.100/26</code>. Блок 64, границы: .0, .64, .128, .192. Адрес .100 попадает во второй блок: адрес сети <code>192.168.10.64</code>, broadcast <code>192.168.10.127</code>, хосты <code>.65 – .126</code>, всего 62 адреса."}
 ],
 key:["Размер блока = 256 − значение интересного октета маски.","Адрес сети — начало блока, broadcast — конец блока.","Хостов в подсети 2^h − 2."]},

{id:"l14",b:1,day:14,t:"Подсети: проектируем сеть",min:8,
 lead:"Обратная задача: не «какая подсеть у адреса», а «как нарезать сеть под нужное число подсетей и хостов».",
 secs:[
  {h:"Две формулы",p:"Пусть у классовой сети взяли <i>s</i> бит под подсети, а на хосты осталось <i>h</i> бит. Тогда подсетей получится <b>2<sup>s</sup></b>, а адресов для хостов в каждой — <b>2<sup>h</sup> − 2</b>. Сумма бит фиксирована: для сети класса C <i>s</i> + <i>h</i> = 8, для класса B — 16, для класса A — 24."},
  {h:"Как выбрать маску",list:["Посчитать, сколько нужно подсетей и сколько хостов в самой большой из них.","Подобрать <i>h</i> так, чтобы 2<sup>h</sup> − 2 покрывало хосты: 50 хостов → h = 6 (62 адреса).","Проверить, что оставшихся бит хватает на нужное число подсетей.","Записать маску: /24 + s бит. Для класса C и h = 6 это /26 — четыре подсети по 62 адреса."]},
  {h:"Пример нарезки",cli:"Дано: 192.168.1.0/24, нужно 4 подсети по ≤ 50 хостов\nМаска: /26 (блок 64)\n  192.168.1.0/26    хосты .1 – .62      broadcast .63\n  192.168.1.64/26   хосты .65 – .126    broadcast .127\n  192.168.1.128/26  хосты .129 – .190   broadcast .191\n  192.168.1.192/26  хосты .193 – .254   broadcast .255"},
  {h:"Каналы между маршрутизаторами",p:"Каналу точка-точка нужны ровно два адреса, поэтому ему выделяют <b>/30</b> — четыре адреса, из них два рабочих. Отдавать такому каналу /24 — это выбросить 252 адреса. На интерфейсах маршрутизаторов адрес задают командой <code>ip address</code> в режиме настройки интерфейса, и маски на двух концах канала обязаны совпадать."}
 ],
 key:["Подсетей 2^s, хостов 2^h − 2, а s + h задано классом сети.","Маску подбирают по самой большой подсети, а не по средней.","Канал между маршрутизаторами — /30."]},

{id:"l15",b:1,day:15,t:"VLSM: подсети разного размера",min:8,
 lead:"В реальном проекте одним отделам нужны сотни адресов, другим — единицы. VLSM позволяет нарезать подсети разного размера из одного блока.",
 secs:[
  {h:"Что такое VLSM",p:"<b>VLSM (Variable-Length Subnet Masking)</b> — использование в одной сети подсетей с разными масками. Одному сегменту достаётся /24, другому /27, каналу между маршрутизаторами — /30. Так расходуется ровно столько адресов, сколько нужно. Требование одно: подсети не должны <b>перекрываться</b>."},
  {h:"Порядок действий",list:["Выписать все сегменты и нужное число хостов в каждом.","Отсортировать <b>от самого большого к самому маленькому</b>.","Каждому по очереди выдать наименьшую подходящую маску, начиная с начала блока.","Следующую подсеть начинать сразу после конца предыдущей."]},
  {h:"Пример",cli:"Блок 172.16.0.0/22, нужно: 500, 200, 60 хостов и два канала\n  500 → /23  172.16.0.0/23     .0.1 – .1.254\n  200 → /24  172.16.2.0/24     .2.1 – .2.254\n   60 → /26  172.16.3.0/26     .3.1 – .3.62\n    2 → /30  172.16.3.64/30    .3.65 – .3.66\n    2 → /30  172.16.3.68/30    .3.69 – .3.70"},
  {h:"Почему сначала большие",p:"Если начать с мелких подсетей, крупная может не поместиться в остаток: у блока под большую подсеть должно быть <b>правильное начало</b>, кратное её размеру. Сортировка по убыванию гарантирует, что каждая подсеть встанет на своё место без дырок и перекрытий."},
  {h:"Как проверять себя",p:"Для каждой выданной подсети считайте её broadcast и убеждайтесь, что следующая начинается строго после него. Перекрытие — самая частая ошибка проектирования: маршрутизатор примет обе записи, а трафик одной из подсетей начнёт уходить не туда."}
 ],
 key:["VLSM = разные маски в одной сети, ни одного перекрытия.","Нарезают от самой большой подсети к самой маленькой.","Начало подсети должно быть кратно её размеру."]},

/* ══ Блок 2 · VLAN, STP, EtherChannel (дни 16–23) ══════ */
{id:"l16",b:2,day:16,t:"VLAN: несколько сетей на одном коммутаторе",min:7,
 lead:"Локальная сеть — это широковещательный домен. VLAN позволяет одному коммутатору держать сразу несколько таких доменов, как будто это разные коммутаторы.",
 secs:[
  {h:"Что такое VLAN",p:"Без VLAN все порты коммутатора — один широковещательный домен: broadcast из любого порта уходит во все остальные. <b>VLAN (virtual LAN)</b> делит порты на группы, и кадр из одной группы никогда не попадает в порты другой. Получается несколько независимых локальных сетей на одном железе — отделы, этажи или типы устройств разводят логически, а не проводами."},
  {h:"Зачем это нужно",list:["Меньше широковещательного трафика: broadcast получают только хосты своей VLAN.","Безопасность: бухгалтерию, гостей и телефоны можно отделить друг от друга.","Гибкость: сотрудник переехал на другой этаж — порт просто переводят в нужную VLAN.","Проще диагностика: проблема обычно ограничена одним широковещательным доменом."]},
  {h:"Одна VLAN — одна подсеть",p:"Каждой VLAN соответствует своя IP-подсеть. Коммутатор второго уровня <b>не пересылает кадры между VLAN</b> — для связи между ними нужен маршрутизатор или коммутатор третьего уровня (об этом — день 18). Номер VLAN и номер подсети совпадать не обязаны, но совпадение (VLAN 10 — 10.0.10.0/24) сильно упрощает жизнь."},
  {h:"Настройка портов доступа",cli:"SW1(config)# vlan 10\nSW1(config-vlan)# name SALES\nSW1(config-vlan)# exit\nSW1(config)# interface range f0/1 - 8\nSW1(config-if-range)# switchport mode access\nSW1(config-if-range)# switchport access vlan 10\n\nSW1# show vlan brief"},
  {h:"Что важно знать",p:"По умолчанию все порты находятся в <b>VLAN 1</b>. Если назначить порту VLAN, которой ещё нет, коммутатор создаст её сам. Порт доступа (<b>access port</b>) принадлежит ровно одной VLAN, а кадры на нём ходят без меток — хост вообще не знает, что он в какой-то VLAN."}
 ],
 key:["VLAN = отдельный широковещательный домен внутри коммутатора.","Каждой VLAN — своя подсеть; между VLAN нужен маршрутизатор.","Порт доступа принадлежит одной VLAN, кадры на нём без меток.","По умолчанию все порты в VLAN 1."]},

{id:"l17",b:2,day:17,t:"Магистрали и 802.1Q",min:8,
 lead:"Когда VLAN растянуты на несколько коммутаторов, прокладывать отдельный кабель под каждую VLAN глупо. Магистраль (trunk) несёт их все по одному каналу.",
 secs:[
  {h:"Метка VLAN",p:"Отправляя кадр в магистраль, коммутатор вставляет в него <b>метку 802.1Q (tag)</b> — 4 байта между MAC-адресом отправителя и полем типа. Принимающий коммутатор читает номер VLAN, снимает метку и отправляет кадр только в порты этой VLAN. Старый протокол Cisco <b>ISL</b> делал то же самое, но на новых коммутаторах его уже нет."},
  {h:"Поля метки",list:["<b>TPID</b> = <code>0x8100</code> — признак того, что кадр помечен.","<b>PCP</b> — 3 бита приоритета для QoS.","<b>DEI</b> — 1 бит «можно отбросить при перегрузке».","<b>VID</b> — 12 бит номера VLAN: 2¹² = 4096 значений, из них 0 и 4095 зарезервированы, рабочих — <b>1–4094</b>. Обычный диапазон — 1–1005, расширенный — 1006–4094."]},
  {h:"Собственная VLAN",p:"Кадры одной VLAN идут по магистрали <b>без метки</b> — это <b>собственная VLAN (native VLAN)</b>, по умолчанию VLAN 1. Принимающая сторона относит кадр без метки к своей собственной VLAN, поэтому она должна <b>совпадать на обоих концах</b>, иначе трафик перетекает между VLAN. Хорошая практика — назначить собственной неиспользуемую VLAN."},
  {h:"Настройка магистрали",cli:"SW1(config)# interface g0/1\nSW1(config-if)# switchport trunk encapsulation dot1q   ← только там, где есть и ISL\nSW1(config-if)# switchport mode trunk\nSW1(config-if)# switchport trunk allowed vlan 10,20,30\nSW1(config-if)# switchport trunk native vlan 1001\n\nSW1# show interfaces trunk"},
  {h:"Список разрешённых VLAN",p:"По умолчанию магистраль пропускает все VLAN. Командой <code>allowed vlan</code> список сужают. Осторожно: <code>switchport trunk allowed vlan 30</code> <b>заменяет</b> список целиком, а чтобы добавить VLAN к уже разрешённым, нужно <code>allowed vlan add 30</code>. Если VLAN не разрешена на магистрали, хосты этой VLAN на разных коммутаторах друг друга не видят — частая причина «пропала связь»."}
 ],
 key:["Магистраль несёт много VLAN; метка 802.1Q — 4 байта, номер VLAN — 12 бит.","Рабочие номера VLAN: 1–4094.","Собственная VLAN идёт без метки и должна совпадать на концах.","allowed vlan заменяет список, allowed vlan add — дополняет."]},

{id:"l18",b:2,day:18,t:"Маршрутизация между VLAN",min:8,
 lead:"VLAN изолированы, но хостам разных отделов всё-таки нужно общаться. Трафик между ними всегда проходит через третий уровень.",
 secs:[
  {h:"Три способа",list:["<b>Отдельный интерфейс маршрутизатора на каждую VLAN</b> — просто, но интерфейсы быстро кончаются.","<b>Маршрутизатор на палочке (router on a stick, ROAS)</b> — одна магистраль до маршрутизатора и по подинтерфейсу на каждую VLAN.","<b>Коммутатор третьего уровня</b> — маршрутизация прямо в коммутаторе через виртуальные интерфейсы VLAN (SVI). Самый быстрый и распространённый вариант."]},
  {h:"Маршрутизатор на палочке",cli:"R1(config)# interface g0/0\nR1(config-if)# no shutdown\nR1(config)# interface g0/0.10\nR1(config-subif)# encapsulation dot1q 10\nR1(config-subif)# ip address 10.0.10.1 255.255.255.0\nR1(config)# interface g0/0.20\nR1(config-subif)# encapsulation dot1q 20\nR1(config-subif)# ip address 10.0.20.1 255.255.255.0"},
  {h:"Как это работает",p:"Порт коммутатора к маршрутизатору настроен магистралью. Кадр из VLAN 10 приходит на подинтерфейс <code>g0/0.10</code>, маршрутизатор решает, куда отправить пакет, и отправляет его обратно по той же магистрали уже с меткой VLAN 20. Адрес подинтерфейса — это шлюз по умолчанию для хостов своей VLAN. Для собственной VLAN пишут <code>encapsulation dot1q 1 native</code> или назначают адрес на сам физический интерфейс. Минус схемы: весь трафик между VLAN проходит по одному кабелю туда и обратно."},
  {h:"Коммутатор третьего уровня",cli:"SW1(config)# ip routing\nSW1(config)# interface vlan 10\nSW1(config-if)# ip address 10.0.10.1 255.255.255.0\nSW1(config-if)# no shutdown\nSW1(config)# interface g0/24\nSW1(config-if)# no switchport              ← routed port к маршрутизатору\nSW1(config-if)# ip address 10.0.99.2 255.255.255.252"},
  {h:"Когда SVI поднимается",p:"Интерфейс <code>vlan 10</code> будет в состоянии up/up, только если VLAN 10 существует на коммутаторе, в ней есть хотя бы один работающий порт доступа или магистраль, пропускающая эту VLAN, и сам SVI не выключен командой <code>shutdown</code>. Без <code>ip routing</code> коммутатор держит адреса на SVI, но пакеты между ними не маршрутизирует."}
 ],
 key:["Между VLAN трафик идёт только через третий уровень.","ROAS: подинтерфейс + encapsulation dot1q N + IP-адрес шлюза.","L3-коммутатор: ip routing и SVI interface vlan N.","SVI поднимается, если VLAN есть и в ней есть живой порт."]},

{id:"l19",b:2,day:19,t:"DTP и VTP",min:7,
 lead:"Два протокола Cisco, которые пытаются настроить за вас магистрали и списки VLAN. Экзамен ждёт, что вы знаете, как они работают — и почему их обычно отключают.",
 secs:[
  {h:"DTP: договориться о магистрали",p:"<b>DTP (Dynamic Trunking Protocol)</b> позволяет двум соседним портам самим решить, быть ли каналу магистралью. Режимы порта: <code>access</code>, <code>trunk</code>, <code>dynamic desirable</code> (сам предлагает магистраль) и <code>dynamic auto</code> (соглашается, если предложат)."},
  {h:"Что получится",list:["desirable + desirable → магистраль.","desirable + auto → магистраль.","<b>auto + auto → доступ</b>: никто не предложил.","trunk + desirable или auto → магистраль.","trunk + access → ошибка конфигурации: одна сторона метит кадры, другая нет."]},
  {h:"Почему DTP отключают",p:"Порт в режиме dynamic может стать магистралью с чужим устройством — злоумышленник получит доступ ко всем VLAN. Поэтому режим задают явно (<code>switchport mode access</code> или <code>trunk</code>), а на магистралях дополнительно выключают переговоры командой <code>switchport nonegotiate</code>."},
  {h:"VTP: общая база VLAN",p:"<b>VTP (VLAN Trunking Protocol)</b> рассылает список VLAN по магистралям, чтобы не создавать их на каждом коммутаторе вручную. Режимы: <b>server</b> — создаёт и меняет VLAN и рассылает изменения; <b>client</b> — принимает их, сам менять не может; <b>transparent</b> — ведёт свою локальную базу и не синхронизируется, но пересылает объявления дальше. Все коммутаторы должны быть в одном домене VTP."},
  {h:"Главная опасность VTP",p:"Каждое изменение увеличивает <b>номер ревизии (revision number)</b>, и коммутаторы принимают базу с бо́льшим номером. Если подключить к сети коммутатор со старой лабораторной конфигурацией и высокой ревизией, он может затереть VLAN во всём домене. Отсюда правило: перед подключением сбрасывать ревизию, а на практике многие сети держат коммутаторы в режиме transparent."}
 ],
 key:["auto + auto = порт доступа, магистраль не поднимется.","Задавайте режим порта явно и отключайте DTP: switchport nonegotiate.","VTP: server меняет, client принимает, transparent живёт сам по себе.","Больший номер ревизии VTP перезаписывает базу VLAN."]},

{id:"l20",b:2,day:20,t:"Spanning Tree: зачем и кто корень",min:8,
 lead:"Резервные каналы между коммутаторами нужны для надёжности, но создают петли. STP оставляет резерв и при этом не даёт кадрам ходить по кругу.",
 secs:[
  {h:"Почему петля — катастрофа",p:"В заголовке Ethernet нет поля TTL, поэтому кадр в петле живёт вечно. Broadcast в кольце из коммутаторов размножается на каждом проходе — это <b>широковещательный шторм (broadcast storm)</b>, который забивает каналы за секунды. Заодно коммутаторы видят один MAC-адрес то на одном порту, то на другом (<b>MAC flapping</b>), а хосты получают дубликаты кадров."},
  {h:"Что делает STP",p:"<b>STP (Spanning Tree Protocol, 802.1D)</b> строит из физической топологии дерево без петель: часть портов переводится в <b>блокировку (blocking)</b> и не пересылает пользовательские кадры. Если рабочий канал откажет, заблокированный порт перейдёт в пересылку. Коммутаторы обмениваются служебными кадрами <b>BPDU</b> каждые 2 секунды."},
  {h:"Идентификатор моста",p:"У каждого коммутатора есть <b>Bridge ID</b>: приоритет (по умолчанию 32768) плюс MAC-адрес. В PVST+ к приоритету прибавляется номер VLAN — <b>extended system ID</b>, поэтому в выводе видно 32769 для VLAN 1. Приоритет меняют только шагами по <b>4096</b>."},
  {h:"Выбор корня",p:"<b>Корневым мостом (root bridge)</b> становится коммутатор с наименьшим Bridge ID: сначала сравнивают приоритет, при равенстве — MAC-адрес. Все порты корневого моста — назначенные (designated) и пересылают трафик. Оставлять выбор корня на волю MAC-адресов плохо: корнем может стать самый старый и медленный коммутатор, поэтому корень назначают явно.",
   cli:"SW1(config)# spanning-tree vlan 10 root primary\n↑ или вручную:\nSW1(config)# spanning-tree vlan 10 priority 4096"}
 ],
 key:["Петля второго уровня = широковещательный шторм: у Ethernet нет TTL.","STP блокирует лишние порты и открывает их при отказе.","Bridge ID = приоритет (32768 + VLAN) + MAC; шаг приоритета — 4096.","Корень — наименьший Bridge ID; все его порты назначенные."]},

{id:"l21",b:2,day:21,t:"Spanning Tree: роли портов и состояния",min:9,
 lead:"После выбора корня каждый коммутатор решает, какой порт ведёт к корню, какой отвечает за сегмент, а какой нужно заблокировать.",
 secs:[
  {h:"Стоимость пути",p:"Путь к корню оценивают по <b>стоимости (root cost)</b> — сумме стоимостей входящих портов по дороге. Стандартные значения: 10 Мбит/с — <b>100</b>, 100 Мбит/с — <b>19</b>, 1 Гбит/с — <b>4</b>, 10 Гбит/с — <b>2</b>. Чем быстрее канал, тем меньше стоимость."},
  {h:"Три роли порта",list:["<b>Корневой порт (root port)</b> — у каждого некорневого коммутатора ровно один: с наименьшей стоимостью до корня. При равенстве — к соседу с наименьшим Bridge ID, затем с наименьшим Port ID соседа.","<b>Назначенный порт (designated port)</b> — по одному на каждый сегмент: тот, что ближе к корню. При равенстве стоимости — у коммутатора с меньшим Bridge ID.","<b>Неназначенный (non-designated)</b> — все остальные: они блокируются."]},
  {h:"Состояния порта",list:["<b>Blocking</b> — только слушает BPDU.","<b>Listening</b> (15 с) — участвует в выборах, MAC-адреса не изучает.","<b>Learning</b> (15 с) — изучает MAC-адреса, но кадры ещё не пересылает.","<b>Forwarding</b> — полноценная работа.","<b>Disabled</b> — порт выключен администратором."]},
  {h:"Таймеры и почему STP медленный",p:"<b>Hello</b> — 2 с между BPDU, <b>Max Age</b> — 20 с без BPDU до признания отказа, <b>Forward Delay</b> — 15 с на listening и столько же на learning. Непрямой отказ может стоить до 20 + 15 + 15 = <b>50 секунд</b> без связи. Для портов к компьютерам это недопустимо долго, поэтому на них включают <b>PortFast</b> — порт сразу переходит в forwarding — и обязательно <b>BPDU Guard</b>, который выключает порт в err-disabled, если в него вдруг пришёл BPDU от коммутатора.",
   cli:"SW1(config-if)# spanning-tree portfast\nSW1(config-if)# spanning-tree bpduguard enable"}
 ],
 key:["Стоимости: 100 / 19 / 4 / 2 для 10 М / 100 М / 1 Г / 10 Г.","Корневой порт — один на коммутатор, назначенный — один на сегмент.","Классический STP сходится до 50 с.","PortFast только для портов к хостам, в паре с BPDU Guard."]},

{id:"l22",b:2,day:22,t:"Rapid Spanning Tree",min:7,
 lead:"RSTP решает ту же задачу, что STP, но за секунды вместо минуты. На современных коммутаторах Cisco включают именно его.",
 secs:[
  {h:"Что изменилось",p:"<b>RSTP (802.1w)</b> не ждёт таймеров, а договаривается с соседом напрямую механизмом <b>предложение/согласие (proposal/agreement)</b>. BPDU шлёт каждый коммутатор, а не только ретранслирует корневые; сосед считается пропавшим после трёх пропущенных hello, то есть примерно через 6 секунд."},
  {h:"Состояния",p:"Вместо пяти состояний три: <b>discarding</b> (объединяет blocking, listening и disabled), <b>learning</b> и <b>forwarding</b>."},
  {h:"Роли портов",list:["<b>Root</b> и <b>designated</b> — как в классическом STP.","<b>Alternate</b> — запасной путь к корню через другой коммутатор: при отказе корневого порта он сразу становится корневым.","<b>Backup</b> — запасной путь к тому же сегменту, что и назначенный порт этого же коммутатора (встречается только с хабами)."]},
  {h:"Типы каналов",p:"<b>Point-to-point</b> — полный дуплекс между двумя коммутаторами: здесь работает быстрый переход. <b>Shared</b> — полудуплекс (хаб): тут RSTP осторожничает как старый STP. <b>Edge</b> — порт к конечному устройству, аналог PortFast. На коммутаторах Cisco RSTP включается в виде <b>Rapid PVST+</b> — отдельное дерево на каждую VLAN.",
   cli:"SW1(config)# spanning-tree mode rapid-pvst\nSW1# show spanning-tree vlan 10"}
 ],
 key:["RSTP сходится за секунды за счёт proposal/agreement.","Состояния: discarding, learning, forwarding.","Alternate — готовый запасной корневой порт.","Cisco: spanning-tree mode rapid-pvst."]},

{id:"l23",b:2,day:23,t:"EtherChannel",min:8,
 lead:"Два кабеля между коммутаторами — это не удвоенная скорость: STP заблокирует один из них. EtherChannel объединяет каналы так, чтобы работали все.",
 secs:[
  {h:"Идея",p:"<b>EtherChannel</b> объединяет до 8 физических каналов в один логический интерфейс <code>port-channel</code>. STP видит его как один канал и ничего не блокирует, а при отказе одного кабеля трафик продолжает идти по остальным без пересчёта дерева."},
  {h:"Балансировка",p:"Один поток (например, одна TCP-сессия) всегда идёт по одному физическому каналу — иначе нарушится порядок кадров. Канал выбирается хешем от адресов: MAC, IP или их сочетания отправителя и получателя. Поэтому балансировка работает по потокам, а не по кадрам, и два хоста с одним большим файлом не получат удвоенную скорость.",
   cli:"SW1(config)# port-channel load-balance src-dst-ip"},
  {h:"Протоколы согласования",list:["<b>LACP</b> (IEEE 802.3ad / 802.1AX, открытый): режимы <code>active</code> (предлагает) и <code>passive</code> (ждёт предложения).","<b>PAgP</b> (Cisco): режимы <code>desirable</code> и <code>auto</code>.","<b>Статически</b>: режим <code>on</code> — без переговоров, обе стороны должны быть on.","Не заработает: passive + passive, auto + auto, а также смешение протоколов."]},
  {h:"Настройка",cli:"SW1(config)# interface range g0/1 - 2\nSW1(config-if-range)# channel-group 1 mode active\nSW1(config)# interface port-channel 1\nSW1(config-if)# switchport mode trunk\n\nSW1# show etherchannel summary     ← флаги: P — в группе, SU — L2 и работает"},
  {h:"Что должно совпадать",p:"У всех портов группы должны совпадать скорость и дуплекс, режим (доступ или магистраль), VLAN доступа или список разрешённых VLAN и собственная VLAN. Порт с отличающимися настройками в группу не войдёт (в выводе будет флаг <b>s</b> — suspended). Бывает и <b>EtherChannel третьего уровня</b>: на <code>port-channel</code> пишут <code>no switchport</code> и назначают IP-адрес."}
 ],
 key:["До 8 каналов в одном port-channel; STP видит один канал.","Балансировка по потокам через хеш адресов.","LACP: active/passive; PAgP: desirable/auto; статически: on.","Настройки всех портов группы должны совпадать."]},

/* ══ Блок 3 · Динамическая маршрутизация (дни 24–29) ═══ */
{id:"l24",b:3,day:24,t:"Динамическая маршрутизация",min:8,
 lead:"Статические маршруты хороши в маленькой сети. В большой маршрутизаторы должны сами узнавать сети и сами перестраиваться при отказах.",
 secs:[
  {h:"Задачи протокола маршрутизации",list:["Найти маршруты ко всем подсетям и занести лучшие в таблицу.","Заметить, что маршрут перестал работать, и убрать его.","Найти замену — как можно быстрее: время до восстановления называют <b>временем конвергенции</b>.","Не допустить маршрутных петель."]},
  {h:"Семейства протоколов",p:"<b>IGP</b> работают внутри одной организации (автономной системы): RIP, EIGRP, OSPF, IS-IS. <b>EGP</b> связывает организации между собой — сегодня это только <b>BGP</b>. Внутри IGP два подхода: <b>дистанционно-векторные (distance vector)</b> протоколы узнают маршруты «со слов соседа» — сеть такая-то, до неё столько-то; <b>протоколы состояния канала (link state)</b> рассылают всем описание своих каналов, и каждый маршрутизатор сам строит полную карту сети и считает по ней кратчайшие пути."},
  {h:"Метрика",p:"Когда к одной сети есть несколько путей <i>одного</i> протокола, выбирается путь с наименьшей <b>метрикой</b>: у RIP это число переходов, у OSPF — стоимость (cost), у EIGRP — формула из полосы и задержки. Пути с одинаковой метрикой попадают в таблицу вместе — это <b>ECMP</b>, балансировка нагрузки."},
  {h:"Административная дистанция",p:"Если одну сеть предлагают <i>разные</i> источники, метрики сравнивать нельзя — у каждого протокола свои единицы. Тогда решает <b>административная дистанция (AD)</b>: мера доверия к источнику, меньше — лучше.",
   cli:"Connected   0      EIGRP        90\nStatic      1      OSPF        110\neBGP       20      RIP         120\n                   EIGRP внешн. 170\n                   iBGP        200"},
  {h:"Порядок выбора",p:"Маршрутизатор решает в три шага: сначала для пакета выбирается запись с <b>самой длинной маской</b>; если одинаковый префикс предлагают разные источники — в таблицу попадает источник с наименьшей <b>AD</b>; внутри одного протокола — путь с наименьшей <b>метрикой</b>. Плавающий статический маршрут — это просто статический маршрут с AD выше, чем у протокола, чтобы он включался только при отказе."}
 ],
 key:["IGP — внутри организации, BGP — между ними.","Distance vector узнаёт от соседей, link state строит полную карту.","Метрика сравнивает пути одного протокола, AD — разные источники.","Порядок: длиннейший префикс → наименьшая AD → наименьшая метрика."]},

{id:"l25",b:3,day:25,t:"RIP и EIGRP",min:8,
 lead:"Два дистанционно-векторных протокола: простой и устаревший RIP и быстрый EIGRP, разработанный Cisco.",
 secs:[
  {h:"RIP",p:"<b>RIP (Routing Information Protocol)</b> считает метрику в <b>переходах (hop count)</b> — сколько маршрутизаторов до сети — и не смотрит на скорость каналов. Максимум <b>15 переходов</b>, 16 означает «недостижима», поэтому RIP годится только для небольших сетей. Полная таблица рассылается каждые 30 секунд; RIPv2 шлёт её на групповой адрес <code>224.0.0.9</code> и передаёт маски (classless).",
   cli:"R1(config)# router rip\nR1(config-router)# version 2\nR1(config-router)# no auto-summary\nR1(config-router)# network 10.0.0.0"},
  {h:"EIGRP",p:"<b>EIGRP</b> — «продвинутый» дистанционно-векторный протокол Cisco (сегодня описан в открытом RFC). Он не рассылает таблицу периодически, а сообщает только об изменениях; соседей ищет приветствиями на <code>224.0.0.10</code>. Метрика по умолчанию считается из <b>полосы (bandwidth)</b> самого медленного канала на пути и суммарной <b>задержки (delay)</b>. Соседями становятся только маршрутизаторы с одинаковым номером автономной системы (AS)."},
  {h:"Преемник и резерв",p:"Лучший путь EIGRP называют <b>successor</b>. Запасной путь, который гарантированно без петли, — <b>feasible successor</b>: он проверяется условием, что сосед сам находится ближе к сети, чем мы через текущий лучший путь. Если successor пропадёт, EIGRP переключится на feasible successor мгновенно. EIGRP умеет и балансировку по путям с <i>разной</i> метрикой — командой <code>variance</code>.",
   cli:"R1(config)# router eigrp 100\nR1(config-router)# network 10.0.12.0 0.0.0.3\n↑ в network указывается обратная маска (wildcard)"}
 ],
 key:["RIP: метрика — переходы, максимум 15, обновления каждые 30 с.","EIGRP: метрика из полосы и задержки, AS у соседей должен совпадать.","Feasible successor — готовый запасной путь без петли.","EIGRP умеет неравную балансировку (variance)."]},

{id:"l26",b:3,day:26,t:"OSPF: как он устроен",min:9,
 lead:"OSPF — главный протокол маршрутизации экзамена. Сначала принцип работы и базовая настройка одной области.",
 secs:[
  {h:"Состояние каналов",p:"Каждый маршрутизатор OSPF описывает свои каналы в сообщениях <b>LSA (Link State Advertisement)</b> и рассылает их соседям, а те — дальше. Все LSA складываются в <b>базу LSDB</b>, одинаковую у всех маршрутизаторов области. По этой карте каждый сам считает кратчайшие пути алгоритмом <b>SPF (Дейкстры)</b> и заносит лучшие в таблицу."},
  {h:"Области",p:"Большую сеть делят на <b>области (areas)</b>, чтобы базы не разрастались. Центральная область — <b>area 0 (backbone)</b>, к ней подключаются все остальные. Маршрутизатор на границе областей — <b>ABR</b>. Для CCNA достаточно понимать <b>одну область</b> — area 0."},
  {h:"Router ID",p:"Каждый маршрутизатор OSPF идентифицируется <b>Router ID</b> в формате IPv4-адреса. Он выбирается так: заданный вручную командой <code>router-id</code>; иначе наибольший адрес loopback-интерфейса; иначе наибольший адрес работающего физического интерфейса. Router ID обязан быть уникальным, а смена его вступает в силу после перезапуска процесса (<code>clear ip ospf process</code>)."},
  {h:"Настройка",cli:"R1(config)# router ospf 1              ← номер процесса важен только локально\nR1(config-router)# router-id 1.1.1.1\nR1(config-router)# network 10.0.12.0 0.0.0.3 area 0\nR1(config-router)# passive-interface g0/1\nR1(config-router)# default-information originate\n\n↑ или прямо на интерфейсе:\nR1(config-if)# ip ospf 1 area 0"},
  {h:"Что делают эти команды",list:["<code>network … area 0</code> включает OSPF на интерфейсах, чей адрес попадает под сеть с обратной маской.","<code>passive-interface</code> — сеть интерфейса анонсируется, но приветствия на нём не рассылаются: для портов к пользователям, где соседей нет.","<code>default-information originate</code> — раздать всем маршрут по умолчанию, если он есть на этом маршрутизаторе.","Приветствия OSPF идут на групповой адрес <code>224.0.0.5</code>."]}
 ],
 key:["LSA → общая LSDB → каждый считает SPF сам.","Area 0 — магистральная область; для CCNA — одна область.","Router ID: вручную → наибольший loopback → наибольший физический.","passive-interface: сеть анонсируется, соседства нет."]},

{id:"l27",b:3,day:27,t:"OSPF: стоимость и соседи",min:8,
 lead:"Почему OSPF выбрал не тот путь и почему маршрутизаторы не становятся соседями — две самые частые задачи на экзамене.",
 secs:[
  {h:"Стоимость",p:"Метрика OSPF — <b>стоимость (cost)</b>, сумма стоимостей исходящих интерфейсов по пути. Стоимость интерфейса = <b>опорная полоса / полоса интерфейса</b>. Опорная полоса по умолчанию — 100 Мбит/с, поэтому FastEthernet, Gigabit и 10-Gigabit получают одинаковую стоимость <b>1</b>, и OSPF их не различает. Лечится увеличением опорной полосы на <i>всех</i> маршрутизаторах или ручной стоимостью.",
   cli:"R1(config-router)# auto-cost reference-bandwidth 100000   ← в Мбит/с\nR1(config-if)# ip ospf cost 10"},
  {h:"Условия соседства",list:["Одна и та же область на обоих концах.","Одна подсеть и одинаковая маска.","Совпадающие таймеры hello и dead (на Ethernet — 10 и 40 секунд).","Совпадающая аутентификация.","Одинаковый MTU — иначе соседи застрянут в ExStart/Exchange.","Уникальные Router ID.","Интерфейс не пассивный."]},
  {h:"Состояния соседа",p:"<b>Down</b> → <b>Init</b> (получил hello, но себя в нём не увидел) → <b>2-Way</b> (увидел себя в hello соседа) → <b>ExStart</b> и <b>Exchange</b> (обмен описаниями баз) → <b>Loading</b> (запрос недостающих LSA) → <b>Full</b> (базы совпадают). Состояния смотрят командой <code>show ip ospf neighbor</code>."}
 ],
 key:["Стоимость = опорная полоса / полоса интерфейса; по умолчанию 100 Мбит/с.","Fast, Gigabit и 10G по умолчанию стоят одинаково — 1.","Соседство требует одной области, подсети, таймеров, MTU и уникальных RID.","Цель — состояние Full."]},

{id:"l28",b:3,day:28,t:"OSPF: типы сетей и DR/BDR",min:8,
 lead:"На общей среде вроде Ethernet маршрутизаторов может быть много. Чтобы они не устанавливали полное соседство каждый с каждым, OSPF выбирает старосту.",
 secs:[
  {h:"Типы сетей",list:["<b>Broadcast</b> — по умолчанию на Ethernet: выбираются DR и BDR.","<b>Point-to-point</b> — по умолчанию на последовательных каналах (HDLC, PPP): только два маршрутизатора, DR не нужен.","<b>Non-broadcast</b> — сети без широковещания; соседей задают вручную."]},
  {h:"DR и BDR",p:"В сегменте broadcast выбирается <b>назначенный маршрутизатор (DR)</b> и <b>резервный (BDR)</b>. Остальные (<b>DROther</b>) доходят до Full только с DR и BDR, а между собой остаются в 2-Way — это нормально, а не ошибка. Обновления DROther отправляют на <code>224.0.0.6</code> (только DR и BDR), а DR раздаёт их всем на <code>224.0.0.5</code>."},
  {h:"Выборы",p:"Побеждает наибольший <b>приоритет интерфейса OSPF</b> (по умолчанию 1), при равенстве — наибольший <b>Router ID</b>. Приоритет 0 означает «никогда не быть DR». Выборы <b>не вытесняющие</b>: если появится маршрутизатор с большим приоритетом, он не отберёт роль у действующего DR — новые выборы будут только после его отказа или перезапуска процесса OSPF.",
   cli:"R1(config-if)# ip ospf priority 255\nR1(config-if)# ip ospf network point-to-point   ← Ethernet между двумя маршрутизаторами"},
  {h:"Практический совет",p:"Если Ethernet соединяет ровно два маршрутизатора, выборы DR — лишняя задержка. Команда <code>ip ospf network point-to-point</code> на обоих концах убирает их, и соседство поднимается быстрее. Тип сети на двух концах должен совпадать, иначе соседство будет неправильным."}
 ],
 key:["Ethernet — broadcast с DR/BDR; последовательный канал — point-to-point.","DROther с DR/BDR — Full, между собой — 2-Way.","Выборы: наибольший приоритет, затем наибольший RID; 0 — не участвует.","DR не вытесняется."]},

{id:"l29",b:3,day:29,t:"Резервирование шлюза: HSRP, VRRP, GLBP",min:7,
 lead:"У хоста один шлюз по умолчанию. Если этот маршрутизатор откажет, хост потеряет связь, даже если рядом стоит второй. Протоколы FHRP это исправляют.",
 secs:[
  {h:"Идея",p:"Два или больше маршрутизаторов делят один <b>виртуальный IP-адрес</b> и <b>виртуальный MAC-адрес</b>. Хостам в качестве шлюза выдают именно виртуальный адрес. Отвечает на него активный маршрутизатор; если он откажет, роль перейдёт к резервному, а тот разошлёт <b>gratuitous ARP</b>, чтобы коммутаторы обновили таблицы MAC. Хосты ничего не заметят."},
  {h:"Три протокола",list:["<b>HSRP</b> (Cisco): роли active и standby; виртуальный MAC <code>0000.0c07.acXX</code> в v1 и <code>0000.0c9f.fXXX</code> в v2; приоритет по умолчанию 100; вытеснение (preempt) по умолчанию <b>выключено</b>.","<b>VRRP</b> (открытый стандарт): роли master и backup; MAC <code>0000.5e00.01XX</code>; группа <code>224.0.0.18</code>; вытеснение по умолчанию <b>включено</b>.","<b>GLBP</b> (Cisco): кроме резервирования ещё и балансирует нагрузку — разным хостам отвечает разными виртуальными MAC; роли AVG и AVF."]},
  {h:"Настройка HSRP",cli:"R1(config)# interface g0/0\nR1(config-if)# standby 1 ip 10.1.1.254\nR1(config-if)# standby 1 priority 110\nR1(config-if)# standby 1 preempt\n\nR1# show standby brief"},
  {h:"Про вытеснение",p:"Без <code>preempt</code> маршрутизатор с большим приоритетом не заберёт роль active у действующего — даже когда вернётся после перезагрузки. Поэтому в HSRP вытеснение включают явно, если нужно, чтобы основным всегда был конкретный маршрутизатор."}
 ],
 key:["FHRP даёт хостам виртуальный шлюз: IP + MAC.","HSRP — Cisco, active/standby, preempt выключен по умолчанию.","VRRP — стандарт, master/backup, preempt включён.","GLBP ещё и балансирует нагрузку."]}
];
